# hypothesis: A plain module-level decorator applied only to __set__, with an undecorated __delete__, keeps the descriptor protocol consistent, so set, get and delete round-trip the stored value at runtime and in the checkers.
from typing import Callable, TypeVar, reveal_type

F = TypeVar('F', bound=Callable[..., object])


def traced(fn: F) -> F:
    return fn


class Slot:
    def __init__(self) -> None:
        self._value: int = 0

    def __get__(self, obj: object, owner: type | None = None) -> int:
        return self._value

    @traced
    def __set__(self, obj: object, value: int) -> None:
        self._value = value

    def __delete__(self, obj: object) -> None:
        self._value = -1


class Host:
    slot = Slot()


h = Host()
reveal_type(h.slot)
h.slot = 5
assert h.slot == 5
del h.slot
assert h.slot == -1
Slot.__set__(Slot(), h, 9)
Slot.__delete__(Slot(), h)
